const topic = msg.topic;
const payload = msg.payload;
const parts = topic.split('/');

const configs = global.get('device_configs') || {};
const acIds = Object.keys(configs)
    .filter(id => configs[id].type === 'ac_controller')
    .sort();

const idx = parseInt(parts[2]);
const deviceId = acIds[idx];
if (!deviceId) return null;

const cfg = configs[deviceId];
const ex = cfg.extra || {};
const gateway = cfg.gateway || ex.gateway;
const attr = parts[3];

const writes = {};
if (attr === 'power') {
    writes['EF00/' + (ex.power_attr || '0101')] = payload === 'ON' ? 1 : 0;
} else if (attr === 'temperature') {
    writes['EF00/' + (ex.ac_temp_attr || '0202')] = parseInt(payload);
} else if (attr === 'fan') {
    writes['EF00/' + (ex.ac_mode_attr || '0405')] = parseInt(payload);
}

msg.topic = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ Device: deviceId, Write: writes });
return msg;

const topic = msg.topic;
const payload = msg.payload;
const parts = topic.split('/');

const configs = global.get('device_configs') || {};
const signIds = Object.keys(configs)
    .filter(id => configs[id].type === 'mcb')
    .sort();

const idx = parseInt(parts[2]);
const deviceId = signIds[idx];
if (!deviceId) return null;

const cfg = configs[deviceId];
const ex = cfg.extra || {};
const gateway = cfg.gateway || ex.gateway;

const val = (payload === 'ON' || payload === '1' || payload === 1) ? 1 : 0;
const powerAttr = ex.power_attr || '0110';

// MCB dung NEW format (giong AC)
msg.topic = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({
    Device: deviceId,
    Write: { ['EF00/' + powerAttr]: val },
    Endpoint: 1
});
msg._hmi_cmd = { device: deviceId, action: payload };
return msg;

if (!msg._state_changed) return null;

const d = msg.device;
const prev = msg._prev_state || {};
const s = d.state;

const configs = global.get('device_configs') || {};
const ids = Object.keys(configs)
    .filter(id => configs[id].type === 'ac_controller')
    .sort();
const idx = ids.indexOf(d.id);
if (idx < 0) return null;

const msgs = [];

if (prev.power !== s.power) {
    msgs.push({ topic: 'bms/ac/' + idx + '/power', payload: s.power ? 'ON' : 'OFF' });
}
if (prev.temperature !== s.temperature) {
    msgs.push({ topic: 'bms/ac/' + idx + '/temperature', payload: String(s.temperature) });
}
if (prev.fan_speed !== s.fan_speed) {
    msgs.push({ topic: 'bms/ac/' + idx + '/fan', payload: String(s.fan_speed) });
}
if (prev.online !== s.online) {
    msgs.push({ topic: 'bms/ac/' + idx + '/online', payload: s.online ? 'ON' : 'OFF' });
}
if (prev.ambient_temp !== s.ambient_temp && s.ambient_temp !== undefined) {
    msgs.push({ topic: 'bms/ac/' + idx + '/room_temp', payload: String(s.ambient_temp) });
}

return [msgs];
